package app.dayflow;
import android.widget.*;
import com.google.android.material.textfield.TextInputEditText;
import org.json.*;
import java.time.*;

final class TaskQuickActions {
 static void show(MainActivity a,JSONObject record,Runnable back){LinearLayout page=a.fullPage("调整安排",back);page.addView(Ui.text(a,record.optString("title"),22,true));page.addView(Ui.help(a,PlanTime.label(record)+(!record.optString("series_id").isEmpty()?" · 仅调整这一次":"")));page.addView(Ui.button(a,"编辑详情",true,()->a.edit(record)));if(!record.optBoolean("all_day")&&!record.optString("start_at").isEmpty()){page.addView(Ui.button(a,"提前30分钟",false,()->shift(a,record,-30,back)));page.addView(Ui.button(a,"延后30分钟",false,()->shift(a,record,30,back)));page.addView(Ui.button(a,"延后1小时",false,()->shift(a,record,60,back)));TextInputEditText minutes=Ui.field(a,page,"自定义分钟（正数延后，负数提前）","",false);minutes.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);page.addView(Ui.button(a,"应用分钟调整",false,()->{try{long value=Long.parseLong(minutes.getText().toString());if(Math.abs(value)>525600)throw new Exception("调整范围需在一年内");shift(a,record,value,back);}catch(Exception e){a.message(e.getMessage());}}));}page.addView(Ui.button(a,"提前一天",false,()->shift(a,record,-1440,back)));page.addView(Ui.button(a,"延后一天",false,()->shift(a,record,1440,back)));page.addView(Ui.button(a,"改到指定日期",false,()->{LocalDateTime start=PlanTime.start(record);MonthBrowser.select(a,start==null?LocalDate.now():start.toLocalDate(),date->{if(start==null){a.message("先在编辑页为事项安排日期");return;}shift(a,record,java.time.temporal.ChronoUnit.DAYS.between(start.toLocalDate(),date)*1440,back);},()->show(a,record,back),false);}));page.addView(Ui.button(a,record.optString("completed").isEmpty()?"标记完成":"恢复待办",false,()->{try{TaskActions.complete(a,record);a.changed();back.run();}catch(Exception e){a.message(e.getMessage());}}));}
 private static void shift(MainActivity a,JSONObject record,long minutes,Runnable back){try{JSONObject r=Data.get(a).resolve(record.optString("id"),record.optString("series_id"),record.optString("occurrence_date"));if(r==null||r.optBoolean("deleted"))throw new Exception("事项已删除，请刷新");if(r.optString("start_at").isEmpty()){if(r.optString("due_date").isEmpty())throw new Exception("请先给事项安排日期");r.put("due_date",LocalDate.parse(r.getString("due_date")).plusDays(minutes/1440).toString());}else{r.put("start_at",LocalDateTime.parse(r.getString("start_at")).plusMinutes(minutes).toString());if(!r.optString("end_at").isEmpty())r.put("end_at",LocalDateTime.parse(r.getString("end_at")).plusMinutes(minutes).toString());}Data.validate(r);Data.get(a).save(r);a.changed();back.run();a.message("已调整，提醒同步更新");}catch(Exception e){a.message(e.getMessage());}}
}
